import{_ as t,c as o,o as i,a2 as r}from"./chunks/framework.CFHYvIe4.js";const h=JSON.parse('{"title":"Mono vs Il2Cpp: Practical Differences for Modders","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mono-il2cpp.md","filePath":"guide/mono-il2cpp.md","lastUpdated":1756461828000}'),a={name:"guide/mono-il2cpp.md"};function s(d,e,n,l,c,p){return i(),o("div",null,e[0]||(e[0]=[r('<h1 id="mono-vs-il2cpp-practical-differences-for-modders" tabindex="-1">Mono vs Il2Cpp: Practical Differences for Modders <a class="header-anchor" href="#mono-vs-il2cpp-practical-differences-for-modders" aria-label="Permalink to &quot;Mono vs Il2Cpp: Practical Differences for Modders&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Note</p><p>While S1API abstracts away the differences between Mono and Il2Cpp, understanding these concepts provides valuable insight into what development without S1API would be like. This guide helps you appreciate how S1API simplifies modding by handling the complexities of both backends for you.</p></div><p>This guide explains the key differences between Mono and Il2Cpp builds of Unity games, with a focus on modding using MelonLoader and S1API. It includes practical advice, code examples, and best practices to help you write mods that work on both platforms.</p><h2 id="what-is-mono" tabindex="-1">What is Mono? <a class="header-anchor" href="#what-is-mono" aria-label="Permalink to &quot;What is Mono?&quot;">​</a></h2><p>Mono is an open-source implementation of the .NET Framework in Unity games:</p><ul><li>C# code is compiled to Intermediate Language (IL)</li><li>IL is interpreted or JIT-compiled at runtime</li><li>Game assemblies are distributed as .dll files with readable metadata</li><li>Reflection and .NET features work as expected</li><li>Modding is straightforward: you can use standard C# features, reflection, and direct type access</li></ul><h2 id="what-is-il2cpp" tabindex="-1">What is Il2Cpp? <a class="header-anchor" href="#what-is-il2cpp" aria-label="Permalink to &quot;What is Il2Cpp?&quot;">​</a></h2><p>Il2Cpp is Unity&#39;s technology for converting C# code to C++:</p><ul><li>IL code is converted to C++ at build time</li><li>C++ is compiled to native machine code (native libraries: .dll, .so, etc.)</li><li>Reflection and some .NET features are limited or behave differently</li><li>Type information may be stripped or obfuscated</li><li>Modding is more challenging: direct access to types and methods is restricted</li></ul><h2 id="key-differences-for-modders" tabindex="-1">Key Differences for Modders <a class="header-anchor" href="#key-differences-for-modders" aria-label="Permalink to &quot;Key Differences for Modders&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Mono (.NET)</th><th>Il2Cpp (Native)</th></tr></thead><tbody><tr><td>Assembly Format</td><td>.dll (managed)</td><td>.dll/.so (native)</td></tr><tr><td>Reflection</td><td>Full support</td><td>Limited/stripped</td></tr><tr><td>Method Pointers</td><td>Directly accessible</td><td>Special handling needed</td></tr><tr><td>Type Information</td><td>Complete</td><td>Often stripped/limited</td></tr><tr><td>Coroutines</td><td>Standard Unity</td><td>Special handling</td></tr><tr><td>Custom Components</td><td>Standard C#</td><td>Requires registration</td></tr><tr><td>Casting</td><td>Standard C#</td><td>Use Il2CppInterop</td></tr><tr><td>Events</td><td>Standard C#</td><td>Use generated methods</td></tr><tr><td>Modding Difficulty</td><td>Easier</td><td>More challenging</td></tr></tbody></table><h2 id="best-practices-for-cross-platform-mods" tabindex="-1">Best Practices for Cross-Platform Mods <a class="header-anchor" href="#best-practices-for-cross-platform-mods" aria-label="Permalink to &quot;Best Practices for Cross-Platform Mods&quot;">​</a></h2><ul><li><strong>Use S1API abstractions</strong>: Always prefer S1API&#39;s interfaces and helpers over direct game references.</li><li><strong>Avoid direct reflection</strong>: Use S1API&#39;s reflection helpers or type mapping.</li><li><strong>Test on both platforms</strong>: If possible, test your mods on both Mono and Il2Cpp builds.</li><li><strong>Conditional compilation</strong>: Use only as directed by S1API documentation.</li><li><strong>Register custom Il2Cpp types</strong>: Always register your custom components if inheriting from Il2Cpp types.</li><li><strong>Use MelonCoroutines</strong>: For coroutines, always use <code>MelonCoroutines</code> for compatibility.</li></ul><h2 id="how-s1api-bridges-the-gap" tabindex="-1">How S1API Bridges the Gap <a class="header-anchor" href="#how-s1api-bridges-the-gap" aria-label="Permalink to &quot;How S1API Bridges the Gap&quot;">​</a></h2><p>S1API provides a unified interface for modding both Mono and Il2Cpp builds by:</p><ol><li><strong>Abstraction Layer</strong>: Wrapping platform-specific code behind common interfaces</li><li><strong>Type Mapping</strong>: Handling differences in type systems automatically</li><li><strong>Reflection Helpers</strong>: Providing alternatives to reflection where needed</li><li><strong>Function Proxying</strong>: Creating proxy methods that work correctly on both platforms</li></ol><p>By following these guidelines and using S1API, you can write mods that are robust and compatible with both Mono and Il2Cpp versions of Schedule One.</p>',17)]))}const m=t(a,[["render",s]]);export{h as __pageData,m as default};
